fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "Auto"
    if (exposureTimeNs >= 1_000_000_000L) {
        val seconds = exposureTimeNs / 1_000_000_000.0
        return if (seconds >= 10 || seconds == seconds.toLong().toDouble()) "${seconds.toLong()}s" else "${"%.1f".format(seconds)}s"
    }
    val denominator = 1_000_000_000.0 / exposureTimeNs
    val rounded = denominator.roundToInt()
    return if (Math.abs(denominator - rounded) < 0.05) "1/${rounded}s" else "1/${String.format("%.1f", denominator)}s"
}

