fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "Auto"

    if (exposureTimeNs >= 500_000_000L) {
        return formatSeconds(exposureTimeNs / 1_000_000_000.0)
    }

    val denominator = (1_000_000_000.0 / exposureTimeNs).roundToInt().coerceAtLeast(1)
    return "1/${denominator}s"
}

private fun formatSeconds(seconds: Double): String {
    if (seconds >= 10.0) {
        return String.format("%.0f", seconds) + "s"
    }
    val text = String.format("%.2f", seconds).trimEnd('0').trimEnd('.')
    return text + "s"

