def _is_square_attacked(board, square, by_side):
    target_rank, target_file = divmod(square, 8)
    white = by_side == "w"

    pawn_rank = target_rank - (1 if white else -1)
    pawn = "P" if white else "p"
    for file_offset in (-1, 1):
