def _update_castling(castling, start, target, moving_piece, captured_piece):
    updated = set(castling)

    if moving_piece == "K":
        updated.discard("K")
        updated.discard("Q")
    elif moving_piece == "k":
        updated.discard("k")
        updated.discard("q")
    elif moving_piece == "R":
        if start == 7:
            updated.discard("K")
        elif start == 0:
            updated.discard("Q")
    elif moving_piece == "r":
        if start == 63:
            updated.discard("k")
        elif start == 56:
            updated.discard("q")

    if captured_piece == "R":
        if target == 7:
            updated.discard("K")
        elif target == 0:
            updated.discard("Q")
    elif captured_piece == "r":
        if target == 63:
            updated.discard("k")
        elif target == 56:
            updated.discard("q")

    return updated


