    for square, piece in enumerate(board):
        if piece == king:
            return square
    return None


def _apply_move(board, side, start, target, promotion, ep_target):
    moving_piece = board[start]
    placed_piece = moving_piece
    if promotion is not None:
        placed_piece = promotion.upper() if side == "w" else promotion

    next_board = board.copy()
    next_board[target] = placed_piece
    next_board[start] = None

    if moving_piece.upper() == "K" and abs(target - start) == 2:
        if target > start:
            rook_start = start + 3
            rook_target = start + 1
        else:
            rook_start = start - 4
            rook_target = start - 1
        next_board[rook_target] = next_board[rook_start]
        next_board[rook_start] = None

    if (
        moving_piece.upper() == "P"
        and target == ep_target
        and board[target] is None
        and abs(target - start) in (7, 9)
    ):
        forward = 1 if side == "w" else -1
        next_board[target - forward * 8] = None

    return next_board


