    next_board = _apply_move(board, side, start, target, promotion, ep_target)
    king_square = _find_king(next_board, side)
    if king_square is None:
        return True

    enemy = "b" if side == "w" else "w"
    return not _is_square_attacked(next_board, king_square, enemy)


